import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        StringBuilder sb = new StringBuilder();

        if (N == 2) {
            sb.append("-1\n");
        } else if (N % 2 == 1) {
            int val = 1;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    sb.append(val++);
                    if (j + 1 < N) sb.append(' ');
                }
                sb.append('\n');
            }
        } else {
            long S = 3L * N / 2;
            long L = S;
            long B = S * (N - 2) * (N + 1) / 2;

            for (int i = 1; i <= N - 1; i++) {
                long base = (long) (i - 1) * S;
                for (int j = 1; j <= N - 1; j++) {
                    sb.append(base + j).append(' ');
                }
                sb.append(base + L).append('\n');
            }

            for (int j = 1; j <= N - 1; j++) {
                sb.append(B + j).append(' ');
            }
            sb.append(B + L).append('\n');
        }

        System.out.print(sb);
    }
}
